#pragma once

#include <string>
#include <fstream>
#include <stdexcept>
#include "INIReader.h"

class INIWriter {
public:
    INIWriter() {}

    static void write(const std::string& filepath, const INIReader& reader, bool overwrite) {
        if (!overwrite) {
            std::ifstream file(filepath);
            if (file.good()) {
                throw std::runtime_error("File already exists");
            }
        }

        std::ofstream outFile(filepath);
        if (!outFile.is_open()) {
            throw std::runtime_error("Failed to open file");
        }

        for (const auto& section : reader.Sections()) {
            outFile << "[" + section + "]\n";
            for (const auto& key : reader.Keys(section)) {
                outFile << key + "=" + reader.Get(section, key) + "\n";
            }
        }
    }
};
